package com.sudoplatform.sudotelephony.internal.domain.entities.phoneMessage

/**
 * Input for [PhoneMessageService.list].
 *
 * @property phoneNumberId [String] ID of the phone number whose messages to list.
 * @property conversationId [String] Limits the list to one conversation.
 * @property sortOrder [SortOrderEntity] Order of the messages.
 * @property limit [Int] Maximum number of items per page.
 * @property nextToken [String] A token generated by a previous call to allow for pagination.
 */
internal data class ListPhoneMessagesInput(
    val phoneNumberId: String,
    val conversationId: String? = null,
    val sortOrder: SortOrderEntity? = null,
    val limit: Int? = null,
    val nextToken: String? = null,
)

/**
 * Output for [PhoneMessageService.list].
 *
 * @property items [List] The sealed messages retrieved on this page.
 * @property nextToken [String] A token to pass to the next call to get the next page.
 */
internal data class ListPhoneMessagesOutput(
    val items: List<SealedPhoneMessageEntity>,
    val nextToken: String? = null,
)

/**
 * Input for [PhoneMessageService.delete].
 *
 * @property ids [List] IDs of the messages to delete.
 */
internal data class DeletePhoneMessagesInput(
    val ids: List<String>,
)

/**
 * Input for [PhoneMessageService.updateSeen].
 *
 * @property ids [List] IDs of the messages to update.
 * @property seen [Boolean] The read state to set.
 */
internal data class UpdatePhoneMessagesInput(
    val ids: List<String>,
    val seen: Boolean,
)

/**
 * The outcome of an operation applied to a batch of messages.
 *
 * @property succeededIds [List] IDs the operation applied to.
 * @property failedIds [List] IDs that were not found or do not belong to the caller.
 */
internal data class PhoneMessageBatchResultEntity(
    val succeededIds: List<String>,
    val failedIds: List<String>,
)

/**
 * Domain service port for phone message operations.
 *
 * Returns messages with their sealed fields still sealed; unsealing needs the device's
 * private key and is done by the use cases.
 */
internal interface PhoneMessageService {
    /**
     * Retrieve one of the caller's phone messages.
     *
     * @param id [String] ID of the message to retrieve.
     * @return The [SealedPhoneMessageEntity], or `null` when no message with [id] belongs to
     *  the caller.
     */
    suspend fun get(id: String): SealedPhoneMessageEntity?

    /**
     * Retrieve a page of a phone number's messages.
     *
     * @param input [ListPhoneMessagesInput] Which messages to list and how to page them.
     * @return A [ListPhoneMessagesOutput] holding the page and its next token.
     */
    suspend fun list(input: ListPhoneMessagesInput): ListPhoneMessagesOutput

    /**
     * Delete a batch of the caller's phone messages.
     *
     * @param input [DeletePhoneMessagesInput] The messages to delete.
     * @return A [PhoneMessageBatchResultEntity] splitting the batch into what was deleted
     *  and what could not be.
     */
    suspend fun delete(input: DeletePhoneMessagesInput): PhoneMessageBatchResultEntity

    /**
     * Change the read state of a batch of the caller's phone messages.
     *
     * @param input [UpdatePhoneMessagesInput] The messages to update and the state to set.
     * @return A [PhoneMessageBatchResultEntity] splitting the batch into what was updated
     *  and what could not be.
     */
    suspend fun updateSeen(input: UpdatePhoneMessagesInput): PhoneMessageBatchResultEntity
}
